body.raw:
{
    "tag": "no_crayon",
    "category": "paper_and_ink",
    "label": "No crayon",
    "description": "Letters or drawings in crayon are refused."
}

{
    "sender": "user",
    "prisoner": 1,
    "relayChapter": 1,
    "ciphertext": "<base64>",
    "nonce": "<base64>",
    "relayNoteCiphertext": "<base64>",
    "relayNoteNonce": "<base64>",
    "envelopes": [
        {
            "readerType": "user",
            "readerId": "{{userId}}",
            "wrappedKey": "<content key sealed to me>"
        },
        {
            "readerType": "chapter",
            "readerId": 1,
            "wrappedKey": "<content key sealed to the relay group>",
            "keyVersion": 1
        }
    ]
}

{
    "name": "Portland ABC",
    "location": {
        "street": "123 Chapter Street"
    },
    "subregion": "Portland, OR",
    "country": "United States",
    "about": "Biweekly letter writing nights.",
    "website": "https://portlandabc.example",
    "email": "letters@portlandabc.example",
    "socialLinks": {
        "instagram": "https://instagram.com/portlandabc"
    },
    "services": [
        "letter_collection",
        "letter_writing_nights",
        "domestic_mailing"
    ]
}

{
    "kind": "group",
    "inviteeName": "Riverside ABC",
    "inviteeEmail": "riverside@example.com",
    "note": "Met at the bookfair; two of us know them"
}

{
    "chapter": 1,
    "publicKey": "<base64 group public key>",
    "wrappedOrgPrivateKey": "<group private key sealed to me>"
}

{
    "chapter": 1,
    "keyVersion": 1,
    "publicKey": "<new group public key>",
    "envelopes": [
        {
            "id": 1,
            "wrappedKey": "<content key re-sealed to the new group key>"
        }
    ],
    "writers": [
        {
            "id": 5,
            "orgWrappedPrivateKey": "<writer private key re-sealed to the new group key>"
        }
    ],
    "members": [
        {
            "user": 2,
            "wrappedOrgPrivateKey": "<new group private key sealed to this member>"
        }
    ]
}
